<?php
namespace App\Services;
use App\Models\{Lead,ProspectingJob}; use Illuminate\Support\Facades\{DB,Http}; use RuntimeException;
class ScraperClient {
 private function http(){ $h=Http::baseUrl(config('kaizen.scraper.base_url'))->timeout(config('kaizen.scraper.timeout')); if($k=config('kaizen.scraper.api_key'))$h=$h->withHeaders(['X-API-Key'=>$k]); return $h; }
 public function create(ProspectingJob $job):string{$r=$this->http()->post('/api/v1/jobs',array_merge($job->search_parameters??[],['name'=>'kaizen-'.$job->id,'keywords'=>$job->keywords,'lat'=>(string)$job->latitude,'lon'=>(string)$job->longitude]));if($r->failed()||!$r->json('id'))throw new RuntimeException('Scraper rejected the job.');return $r->json('id');}
 public function status(ProspectingJob $job):array{$r=$this->http()->get('/api/v1/jobs/'.$job->scraper_job_id);if($r->failed())throw new RuntimeException('Scraper status unavailable.');return $r->json();}
 public function import(ProspectingJob $job,?string $claimToken=null,?callable $renewClaim=null):ScraperImportOutcome{$r=$this->http()->get('/api/v1/jobs/'.$job->scraper_job_id.'/download');if($r->failed())throw new RuntimeException('Scraper results unavailable.');$body=$r->body();if(strlen($body)>(int)config('kaizen.scraper.import_max_bytes',25*1024*1024))throw new RuntimeException('Scraper results exceed the configured size limit.');$s=fopen('php://temp','r+');fwrite($s,$body);rewind($s);$head=fgetcsv($s);if($head===false||$head===[null]){fclose($s);return new ScraperImportOutcome(0,0,0,true);}$head=array_map(fn($v)=>trim((string)$v),$head);$a=$u=$j=$n=0;$max=(int)config('kaizen.scraper.import_max_rows',10000);while(($row=fgetcsv($s))!==false){if($row===[null]||(count($row)===1&&trim((string)$row[0])===''))continue;if(++$n>$max)throw new RuntimeException('Scraper results exceed the configured row limit.');if(count($row)>count($head)){$j++;continue;}$data=array_combine($head,array_pad($row,count($head),''));if(!$data){$j++;continue;}$p=trim((string)($data['place_id']??''));$c=trim((string)($data['cid']??''));$external=$p!==''?$p:($c!==''?$c:null);if($external===null){$j++;continue;}if($renewClaim&&!$renewClaim()){fclose($s);return new ScraperImportOutcome($a,$u,$j,false,true);}$old=DB::transaction(function()use($job,$claimToken,$external,$data){if($claimToken&&!ProspectingJob::whereKey($job->id)->where('polling_claim_token',$claimToken)->lockForUpdate()->exists())return null;$lead=Lead::firstOrCreate(['user_id'=>$job->user_id,'external_place_id'=>$external],['prospecting_job_id'=>$job->id,'name'=>$data['title']??'','phone'=>$data['phone']??null,'email'=>$data['emails']??null,'website'=>$data['website']??null,'category'=>$data['category']??null,'address'=>$data['address']??null,'latitude'=>is_numeric($data['latitude']??null)?$data['latitude']:null,'longitude'=>is_numeric($data['longitude']??null)?$data['longitude']:null,'source'=>'google_maps','raw_data'=>$data]);return !$lead->wasRecentlyCreated;});if($old===null){fclose($s);return new ScraperImportOutcome($a,$u,$j,false,true);}$old?$u++:$a++;}fclose($s);return new ScraperImportOutcome($a,$u,$j,true);}
}
